    ServletRequest request = Mockito.mock(ServletRequest.class);
    Mockito.when(request.getRemoteAddr()).thenReturn(null);
    ServletResponse response = Mockito.mock(ServletResponse.class);
    final AtomicBoolean invoked = new AtomicBoolean();
    FilterChain chain = new FilterChain() {

        @Override
        public void doFilter(ServletRequest servletRequest, ServletResponse servletResponse) throws IOException, ServletException {
            Assert.assertTrue(HostnameFilter.get().contains("???"));
            invoked.set(true);
        }
    };
    Filter filter = new HostnameFilter();
    filter.init(null);
    Assert.assertNull(HostnameFilter.get());
    filter.doFilter(request, response, chain);
    Assert.assertTrue(invoked.get());
    Assert.assertNull(HostnameFilter.get());
    filter.destroy();
}

@Test
public void testXFrameOptionAgainstClickjackingAdded() throws Exception {
    ServletRequest request = Mockito.mock(ServletRequest.class);
    HttpServletResponse response = Mockito.mock(HttpServletResponse.class);
    doNothing().when(response).addHeader(any(String.class), any(String.class));
    final AtomicBoolean invoked = new AtomicBoolean();
    FilterChain chain = new FilterChain() {

        @Override
        public void doFilter(ServletRequest servletRequest, ServletResponse servletResponse) {
            invoked.set(true);
        }
    };
    Filter filter = new HttpResponseHeaderFilter();
    filter.init(null);
    filter.doFilter(request, response, chain);
    verify(response).addHeader(HttpResponseHeaderFilter.X_FRAME_OPTIONS, HttpResponseHeaderFilter.X_FRAME_OPTION_DENY);
    assertTrue("Filter is not invoked", invoked.get());
    filter.destroy();
}

@Test
public void testRetryCountOperations() {
    final SLACalcStatus status = new SLACalcStatus();
    assertEquals("initial retryCount mismatch", 0, status.getRetryCount());
    status.incrementRetryCount();
    status.incrementRetryCount();
    status.incrementRetryCount();
    assertEquals("retryCount mismatch after increments", 3, status.getRetryCount());
    status.resetRetryCount();
    assertEquals("retryCount mismatch after reset", 0, status.getRetryCount());
}

